extern alias apiv5;
using Npgsql;using SanSo.Api.V2;using Xunit;using InventoryStore=apiv5::SanSo.Api.V5.PostgresInventoryStoreV2;
namespace SanSo.Api.V5.Tests;
public sealed class PostgresInventoryConcurrencyV3Tests
{
 [Fact]public async Task LastUnitHasExactlyOneWinnerAndSourceRetryIsIdempotent(){var cs=Environment.GetEnvironmentVariable("SANSO_RUNTIME_POSTGRES");if(string.IsNullOrWhiteSpace(cs))return;var tenant=Guid.NewGuid();var product=Guid.NewGuid();var location=Guid.NewGuid();var sku=$"LAST-{Guid.NewGuid():N}";await Seed(cs,tenant,product,location,sku);await using var source=NpgsqlDataSource.Create(cs);var store=new InventoryStore(source);var results=await Task.WhenAll(Attempt(store,tenant.ToString(),sku,"reserve-a"),Attempt(store,tenant.ToString(),sku,"reserve-b"));Assert.Single(results,x=>x.Success);Assert.Single(results,x=>!x.Success&&x.Conflict);var winner=results.Single(x=>x.Success);var retry=await store.Reserve(tenant.ToString(),sku,1,winner.SourceKey,default);Assert.Equal(0,retry.Available);Assert.Equal(1,retry.Version);await using var c=new NpgsqlConnection(cs);await c.OpenAsync();await using var q=c.CreateCommand();q.CommandText="SELECT reserved,version,(SELECT count(*) FROM inventory_movements WHERE organization_id=$1 AND type='RESERVE') FROM inventory_balances WHERE organization_id=$1 AND product_id=$2 AND location_id=$3";q.Parameters.AddWithValue(tenant);q.Parameters.AddWithValue(product);q.Parameters.AddWithValue(location);await using var r=await q.ExecuteReaderAsync();Assert.True(await r.ReadAsync());Assert.Equal(1,r.GetInt32(0));Assert.Equal(1,r.GetInt64(1));Assert.Equal(1,r.GetInt64(2));}
 static async Task<(bool Success,bool Conflict,string SourceKey)> Attempt(InventoryStore store,string tenant,string sku,string key){try{await store.Reserve(tenant,sku,1,key,default);return(true,false,key);}catch(InventoryConflictException){return(false,true,key);}}static async Task Seed(string cs,Guid tenant,Guid product,Guid location,string sku){await using var c=new NpgsqlConnection(cs);await c.OpenAsync();await using var tx=await c.BeginTransactionAsync();foreach(var item in new[]{(Sql:"INSERT INTO organizations(id,slug,name) VALUES($1,$2,'Inventory test')",Args:new object[]{tenant,$"inventory-{tenant:N}"}),(Sql:"INSERT INTO products(id,organization_id,name,canonical_sku) VALUES($1,$2,'Last unit',$3)",Args:new object[]{product,tenant,sku}),(Sql:"INSERT INTO inventory_locations(id,organization_id,code,name) VALUES($1,$2,'MAIN','Main')",Args:new object[]{location,tenant}),(Sql:"INSERT INTO inventory_balances(organization_id,product_id,location_id,on_hand,reserved,quarantine) VALUES($1,$2,$3,1,0,0)",Args:new object[]{tenant,product,location})}){await using var q=c.CreateCommand();q.Transaction=tx;q.CommandText=item.Sql;foreach(var value in item.Args)q.Parameters.AddWithValue(value);await q.ExecuteNonQueryAsync();}await tx.CommitAsync();}
}
